import Templates from 'core/templates';
import {call as ajaxCall} from 'core/ajax';
import {getString} from 'core/str';
import Notification from 'core/notification';
import {getContextId} from '../context';
import {iconPair, iconView} from './icon_pair';

export default {
    id: 'accordion',
    titleString: 'block_accordion_title',
    icon: '📑',
    defaultData: {
        title: '',
        color: '#3b82f6',
        bg: '#ffffff',
        // Background of the title bar. Empty (a block saved before it existed) is the colour of the content.
        headerBg: '',
        // Colour of the text of the content. Empty is the colour of the page's own text.
        contentColor: '',
        // Whether the accordion opens and closes with a movement.
        animate: true,
        icon: '❯ / ❯',
        state: 'closed',
        content: '',
        hoverEffect: 'none',
        openSound: 'none'
    },

    // Exclude strings and rich text from the Base64 state chip.
    excludeFromState: ['title', 'content'],

    // Extract the text back from the live Moodle DOM node. Both fields fall back to empty
    // (defense in depth), never to whatever state already held, when the expected child is
    // missing — e.g. a value that survived from an attacker-controlled data-slms-state.
    extractDOM: (node, state) => {
        const titleNode = node.querySelector('.slms-acc-title');
        state.title = titleNode ? titleNode.textContent.trim() : '';

        const contentNode = node.querySelector('.studiolms-editable-area');
        state.content = contentNode ? contentNode.innerHTML : '';
    },

    buildToolbar: async(container, data, onUpdate, PopupManager) => {
        try {
            const {html, js} = await Templates.renderForPromise('tiny_studiolms/toolbar_accordion', {});
            Templates.replaceNodeContents(container, html, js);

            const btnDesign = container.querySelector('#tb-acc-design');

            if (btnDesign) {
                btnDesign.addEventListener('click', () => {
                    const tplData = Object.assign({}, data);

                    // Maps the selected icon to the Mustache variable.
                    const iconKey = {
                        '❯ / ❯': 'icon_chevron',
                        '➕ / ➖': 'icon_plus',
                        '📁 / 📂': 'icon_folder',
                        '▶ / ▼': 'icon_triangle'
                    }[iconPair(data.icon)] || 'icon_chevron';

                    tplData[iconKey] = true;
                    tplData.headerBgValue = data.headerBg || data.bg;

                    tplData[`hover_${data.hoverEffect || 'none'}`] = true;
                    tplData[`sound_opt_${data.openSound || 'none'}`] = true;
                    tplData.isOpen = data.state === 'open';
                    tplData.isClosed = data.state === 'closed';
                    tplData.animate = data.animate !== false;
                    tplData.contentColorValue = data.contentColor || '#212529';

                    PopupManager.open(btnDesign, 'tiny_studiolms/popup_accordion_design', tplData, (popup) => {
                        const propMap = {
                            '#pop_acc_color': 'color',
                            '#pop_acc_bg': 'bg',
                            '#pop_acc_header_bg': 'headerBg',
                            '#pop_acc_content_color': 'contentColor',
                            '#pop_acc_icon': 'icon',
                            '#pop_acc_hover': 'hoverEffect',
                            '#pop_acc_sound': 'openSound',
                            '#pop_acc_state': 'state'
                        };
                        Object.keys(propMap).forEach(selector => {
                            const el = popup.querySelector(selector);
                            if (el) {
                                el.addEventListener('input', (ev) => {
                                    data[propMap[selector]] = ev.target.value;
                                    onUpdate(data);
                                });
                            }
                        });

                        const animateEl = popup.querySelector('#pop_acc_animate');
                        animateEl?.addEventListener('change', () => {
                            data.animate = animateEl.checked;
                            onUpdate(data);
                        });

                        const aiBtnEl = popup.querySelector('#accordion-ai-btn');
                        const aiPromptEl = popup.querySelector('#accordion_ai_prompt');
                        const aiSpinner = popup.querySelector('#accordion-ai-spinner');
                        const aiError = popup.querySelector('#accordion-ai-error');

                        if (aiBtnEl && aiPromptEl) {
                            aiBtnEl.addEventListener('click', async() => {
                                const prompt = aiPromptEl.value.trim();
                                if (!prompt) {
                                    return;
                                }
                                aiBtnEl.disabled = true;
                                aiSpinner?.classList.remove('d-none');
                                if (aiError) {
                                    aiError.textContent = '';
                                    aiError.classList.add('d-none');
                                }
                                try {
                                    const [promise] = ajaxCall([{
                                        methodname: 'tiny_studiolms_generate_accordion',
                                        args: {topic: prompt, contextid: getContextId()},
                                    }]);
                                    const result = await promise;
                                    if (result.title) {
                                        data.title = result.title;
                                    }
                                    data.content = result.content || '';
                                    onUpdate(data);
                                } catch (err) {
                                    if (aiError) {
                                        // The err.message is already the translated moodle_exception text the
                                        // server sent (accordion_ai_error) — no need to fetch it again client-side.
                                        aiError.textContent = err.message;
                                        aiError.classList.remove('d-none');
                                    }
                                } finally {
                                    aiBtnEl.disabled = false;
                                    aiSpinner?.classList.add('d-none');
                                }
                            });
                        }
                    });
                });
            }

        } catch (error) {
            // A genuinely unexpected failure (a template/DOM error, not an anticipated business
            // rule), so it goes through Notification.exception() instead of inline text —
            // reserved for real bugs, not routine validation failures.
            container.innerHTML = '';
            Notification.exception(error);
        }
    },

    renderHtml: async(data) => {
        const templateData = Object.assign({}, data);
        templateData.isOpen = data.state === 'open';
        templateData.animate = data.animate !== false;
        Object.assign(templateData, iconView(data.icon));

        if (!templateData.title || templateData.title.trim() === '') {
            templateData.title = await getString('accordion_default_title', 'tiny_studiolms');
        }
        if (!templateData.content || templateData.content.trim() === '') {
            templateData.content = await getString('default_accordion_content', 'tiny_studiolms');
        }

        return Templates.render('tiny_studiolms/block_accordion', templateData);
    }
};
